with TransactionsByAccount as (select account_id, round(stddev(amount), 2) as stddev_amount, sort_array(collect_set(merchant)) as merchant_list from transactions where not is_flagged group by account_id) select accounts.account_type, TransactionsByAccount.stddev_amount, TransactionsByAccount.merchant_list from accounts left join TransactionsByAccount on accounts.id = TransactionsByAccount.account_id where TransactionsByAccount.stddev_amount > 68 order by account_type desc;
